data class User(val id: String, val name: String, val age: Int = 0)

fun main() {
    val users = listOf(
        User("u1", "Alice", 25),
        User("u2", "Bob", 30)
    )

    val adults = users.filter { it.age >= 18 }
        .sortedBy { it.name }
        .map { it.name }

    println(adults)
}

